        const __m128d z116 = _mm_fmadd_pd(_wc14_n, z98, _mm_mul_pd(_ws14_n, _mm_permute_pd(z98, 0x1)));
        const __m128d z99 = _mm_fmadd_pd(_mm_set1_pd(0.70710678118654757), z97, z41);
        const __m128d z108 = _mm_fmadd_pd(_wc6_n, z99, _mm_mul_pd(_ws6_n, _mm_permute_pd(z99, 0x1)));
        const __m128d z101 = _mm_sub_pd(z45, z100);
        const __m128d z117 = _mm_fmadd_pd(_wc15_n, z101, _mm_mul_pd(_ws15_n, _mm_permute_pd(z101, 0x1)));
        const __m128d z102 = _mm_add_pd(z45, z100);
        const __m128d z109 = _mm_fmadd_pd(_wc7_n, z102, _mm_mul_pd(_ws7_n, _mm_permute_pd(z102, 0x1)));
        _mm_storeu_pd(&zout[2*((size_t)0*OLs + (size_t)k*OGs)], z79);
        _mm_storeu_pd(&zout[2*((size_t)1*OLs + (size_t)k*OGs)], z103);
        _mm_storeu_pd(&zout[2*((size_t)2*OLs + (size_t)k*OGs)], z104);
        _mm_storeu_pd(&zout[2*((size_t)3*OLs + (size_t)k*OGs)], z105);
        _mm_storeu_pd(&zout[2*((size_t)4*OLs + (size_t)k*OGs)], z106);
        _mm_storeu_pd(&zout[2*((size_t)5*OLs + (size_t)k*OGs)], z107);
        _mm_storeu_pd(&zout[2*((size_t)6*OLs + (size_t)k*OGs)], z108);
        _mm_storeu_pd(&zout[2*((size_t)7*OLs + (size_t)k*OGs)], z109);
        _mm_storeu_pd(&zout[2*((size_t)8*OLs + (size_t)k*OGs)], z110);
        _mm_storeu_pd(&zout[2*((size_t)9*OLs + (size_t)k*OGs)], z111);
        _mm_storeu_pd(&zout[2*((size_t)10*OLs + (size_t)k*OGs)], z112);
